from docx import Document
from docx.shared import Pt, RGBColor, Inches, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_ORIENT
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

SEV_COLORS={"CRITICAL":"C00000","HIGH":"E26B0A","MEDIUM":"BF9000","LOW":"548235","WITHIN MARKET":"548235"}

def shade(cell, hexcolor):
    tcPr=cell._tc.get_or_add_tcPr()
    shd=OxmlElement("w:shd"); shd.set(qn("w:val"),"clear"); shd.set(qn("w:color"),"auto"); shd.set(qn("w:fill"),hexcolor)
    tcPr.append(shd)

def set_repeat_header(row):
    trPr=row._tr.get_or_add_trPr()
    el=OxmlElement("w:tblHeader"); el.set(qn("w:val"),"true"); trPr.append(el)

def add_runs(p, text, size=None, bold_all=False, italic=False, color=None):
    # supports **bold** markup
    parts=text.split("**")
    for i,part in enumerate(parts):
        if not part: continue
        r=p.add_run(part)
        r.bold = bold_all or (i%2==1)
        r.italic=italic
        if size: r.font.size=Pt(size)
        if color: r.font.color.rgb=RGBColor.from_string(color)
    return p

def para(doc, text, size=10.5, style=None, bold=False, italic=False, align=None, space_after=6, color=None, indent=None):
    p=doc.add_paragraph(style=style) if style else doc.add_paragraph()
    add_runs(p,text,size=size,bold_all=bold,italic=italic,color=color)
    p.paragraph_format.space_after=Pt(space_after)
    if align=="center": p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    if align=="justify": p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    if indent: p.paragraph_format.left_indent=Inches(indent)
    return p

def bullet(doc, text, size=10.5, level=0):
    p=doc.add_paragraph(style="List Bullet" if level==0 else "List Bullet 2")
    add_runs(p,text,size=size)
    p.paragraph_format.space_after=Pt(3)
    return p

def numbered(doc, text, size=10.5):
    p=doc.add_paragraph(style="List Number")
    add_runs(p,text,size=size)
    p.paragraph_format.space_after=Pt(3)
    return p

def heading(doc, text, level=1):
    h=doc.add_heading(text, level=level)
    for r in h.runs:
        r.font.color.rgb=RGBColor(0x1F,0x38,0x64)
    return h

def table(doc, header, rows, widths=None, size=9, header_fill="1F3864", sev_col=None, zebra=True):
    t=doc.add_table(rows=1, cols=len(header))
    t.style="Table Grid"
    t.alignment=WD_TABLE_ALIGNMENT.CENTER
    hdr=t.rows[0]
    set_repeat_header(hdr)
    for i,h in enumerate(header):
        c=hdr.cells[i]; c.text=""
        p=c.paragraphs[0]; r=p.add_run(h); r.bold=True; r.font.size=Pt(size); r.font.color.rgb=RGBColor(0xFF,0xFF,0xFF)
        shade(c,header_fill)
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            c=cells[i]; c.text=""
            lines=str(val).split("\n")
            for li,line in enumerate(lines):
                p=c.paragraphs[0] if li==0 else c.add_paragraph()
                p.paragraph_format.space_after=Pt(1)
                add_runs(p,line,size=size)
            if sev_col is not None and i==sev_col:
                key=str(val).split()[0].upper() if val else ""
                key="WITHIN MARKET" if str(val).upper().startswith("WITHIN") else key
                if key in SEV_COLORS:
                    for p in c.paragraphs:
                        for r in p.runs: r.bold=True; r.font.color.rgb=RGBColor(0xFF,0xFF,0xFF)
                    shade(c,SEV_COLORS[key])
            elif zebra and ri%2==1:
                shade(c,"F2F2F2")
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths):
                row.cells[i].width=Inches(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def new_section(doc, landscape):
    from docx.enum.section import WD_SECTION
    sec=doc.add_section(WD_SECTION.NEW_PAGE)
    if landscape:
        sec.orientation=WD_ORIENT.LANDSCAPE
        sec.page_width, sec.page_height = Inches(11), Inches(8.5)
    else:
        sec.orientation=WD_ORIENT.PORTRAIT
        sec.page_width, sec.page_height = Inches(8.5), Inches(11)
    for m in ("left_margin","right_margin"): setattr(sec,m,Inches(0.7))
    sec.top_margin=Inches(0.7); sec.bottom_margin=Inches(0.7)
    return sec
